public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String first = strings.get(0);
    int n = first.length();
    if (n == 0) {
        return 0;
    }
    // Helper to reverse a string
    java.util.function.Function<String, String> reverse = s -> new StringBuilder(s).reverse().toString();
    // Search lengths from longest to shortest
    for (int len = n; len >= 1; len--) {
        // Generate all substrings of length len in the first string
        for (int i = 0; i + len <= n; i++) {
            String candidate = first.substring(i, i + len);
            String revCandidate = reverse.apply(candidate);
            boolean valid = true;
            for (String str : strings) {
                if (!(str.contains(candidate) || str.contains(revCandidate))) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    Set<String> common = null;
    for (String s : strings) {
        Set<String> subs = new HashSet<>();
        int n = s.length();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                String sub = s.substring(i, j);
                subs.add(sub);
                subs.add(new StringBuilder(sub).reverse().toString());
            }
        }
        if (common == null) {
            common = subs;
        } else {
            common.retainAll(subs);
        }
        if (common.isEmpty()) {
            return 0;
        }
    }
    int maxLen = 0;
    for (String str : common) {
        if (str.length() > maxLen) {
            maxLen = str.length();
        }
    }
    return maxLen;
}

