public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int num = strings.size();
    // Build sets of all substrings for each string
    List<HashSet<String>> substrSets = new ArrayList<>(num);
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) s = "";
        int len = s.length();
        minLen = Math.min(minLen, len);
        HashSet<String> set = new HashSet<>();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                set.add(s.substring(i, j));
            }
        }
        substrSets.add(set);
    }
    if (minLen == 0) return 0;
    String base = strings.get(0);
    // Try lengths from longest to shortest
    for (int l = minLen; l >= 1; l--) {
        int baseLen = base.length();
        for (int i = 0; i <= baseLen - l; i++) {
            String cand = base.substring(i, i + l);
            String rev = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (int idx = 0; idx < num; idx++) {
                HashSet<String> set = substrSets.get(idx);
                if (!(set.contains(cand) || set.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) return l;
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest string to minimize candidate substrings
    int minIndex = 0;
    int minLen = strings.get(0).length();
    for (int i = 1; i < strings.size(); i++) {
        int len = strings.get(i).length();
        if (len < minLen) {
            minLen = len;
            minIndex = i;
        }
    }
    String base = strings.get(minIndex);
    // Iterate lengths from longest to shortest
    for (int len = minLen; len >= 1; len--) {
        for (int start = 0; start <= base.length() - len; start++) {
            String sub = base.substring(start, start + len);
            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (!s.contains(sub) && !s.contains(rev)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    boolean[][] visited = new boolean[rows][];
    for (int i = 0; i < rows; i++) {
        visited[i] = new boolean[grid[i].length];
    }
    int count = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < grid[r].length; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                count++;
                // Depth-first search using a stack
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0];
                    int cc = pos[1];
                    for (int d = 0; d < 8; d++) {
                        int nr = cr + dr[d];
                        int nc = cc + dc[d];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < grid[nr].length
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return count;
}

