                stackR[top] = i;
                stackC[top] = j;
                top++;
                visited[i][j] = true;
                while (top > 0) {
                    top--;
                    int r = stackR[top];
                    int c = stackC[top];
                    for (int k = 0; k < 8; k++) {
                        int nr = r + dr[k];
                        int nc = c + dc[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stackR[top] = nr;
