public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) return 0;
    int n = grid.length;
    int m = grid[0].length;
    boolean[][] visited = new boolean[n][m];
    int count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                count++;
                dfs(grid, visited, i, j);
            }
        }
    }
    return count;
}

private static void dfs(char[][] grid, boolean[][] visited, int r, int c) {
    int n = grid.length;
    int m = grid[0].length;
    visited[r][c] = true;
    for (int dr = -1; dr <= 1; dr++) {
        for (int dc = -1; dc <= 1; dc++) {
            if (dr == 0 && dc == 0) continue;
            int nr = r + dr;
            int nc = c + dc;
            if (nr >= 0 && nr < n && nc >= 0 && nc < m &&
                !visited[nr][nc] && grid[nr][nc] == '@') {
                dfs(grid, visited, nr, nc);
            }
        }
    }
}

