public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // If start equals end, we can stay where we are
    boolean same = true;
    for (int i = 0; i < start.length; i++) {
        if (start[i] != end[i]) {
            same = false;
            break;
        }
    }
    if (same) return "can be travelled";

    // If no paths, then cannot travel
    if (paths == null || paths.length == 0) return "cannot be travelled";

    int dim = start.length;
    // Build adjacency map
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    java.util.Set<String> nodes = new java.util.HashSet<>();

    for (int[] p : paths) {
        if (p.length != 2 * dim) continue; // invalid path entry
        int[] a = new int[dim];
        int[] b = new int[dim];
        for (int i = 0; i < dim; i++) {
            a[i] = p[i];
            b[i] = p[dim + i];
        }
        String keyA = java.util.Arrays.toString(a);
        String keyB = java.util.Arrays.toString(b);
        graph.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        graph.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
        nodes.add(keyA);
        nodes.add(keyB);
    }

    // Perform BFS from start to end
    String startKey = java.util.Arrays.toString(start);
    String endKey = java.util.Arrays.toString(end);

    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) return "can be travelled";
        java.util.List<String> neighbors = graph.getOrDefault(current, java.util.Collections.emptyList());
        for (String neigh : neighbors) {
            if (!visited.contains(neigh)) {
                visited.add(neigh);
                queue.add(neigh);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    int startNode = start[0];
    int endNode = end[0];
    if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
        return "cannot be travelled";
    }
    boolean[] visited = new boolean[n];
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    visited[startNode] = true;
    queue.offer(startNode);
    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == endNode) {
            return "can be travelled";
        }
        for (int[] path : paths) {
            if (path == null || path.length < 2) {
                continue;
            }
            int a = path[0];
            int b = path[1];
            if (a == current && !visited[b]) {
                visited[b] = true;
                queue.offer(b);
            } else if (b == current && !visited[a]) {
                visited[a] = true;
                queue.offer(a);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length < 2 || end.length < 2) {
        return "cannot be travelled";
    }
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    if (sx < 0 || sx >= n || sy < 0 || sy >= n || ex < 0 || ex >= n || ey < 0 || ey >= n) {
        return "cannot be travelled";
    }
    int totalNodes = n * n;
    int startId = sx * n + sy;
    int endId = ex * n + ey;
    if (startId == endId) {
        return "can be travelled";
    }

    int[] degree = new int[totalNodes];
    for (int i = 0; i < paths.length; i++) {
        int[] p = paths[i];
        if (p.length < 4) continue;
        int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
            continue;
        }
        int id1 = x1 * n + y1;
        int id2 = x2 * n + y2;
        degree[id1]++;
        degree[id2]++;
    }

    int[][] neighbors = new int[totalNodes][];
    for (int i = 0; i < totalNodes; i++) {
        neighbors[i] = new int[degree[i]];
    }
    int[] idx = new int[totalNodes];
    for (int i = 0; i < paths.length; i++) {
        int[] p = paths[i];
        if (p.length < 4) continue;
        int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
            continue;
        }
        int id1 = x1 * n + y1;
        int id2 = x2 * n + y2;
        neighbors[id1][idx[id1]++] = id2;
        neighbors[id2][idx[id2]++] = id1;
    }

    boolean[] visited = new boolean[totalNodes];
    int[] queue = new int[totalNodes];
    int head = 0, tail = 0;
    visited[startId] = true;
    queue[tail++] = startId;
    while (head < tail) {
        int cur = queue[head++];
        if (cur == endId) {
            return "can be travelled";
        }
        int[] neigh = neighbors[cur];
        for (int j = 0; j < neigh.length; j++) {
            int nb = neigh[j];
            if (!visited[nb]) {
                visited[nb] = true;
                queue[tail++] = nb;
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to serialize coordinates
    java.util.function.Function<int[], String> serialize = coords -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coords.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coords[i]);
        }
        return sb.toString();
    };

    String startKey = serialize.apply(start);
    String endKey = serialize.apply(end);
    if (startKey.equals(endKey)) return "can be travelled";

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path.length < 2 * n) continue; // invalid path entry
        int[] srcArr = new int[n];
        int[] dstArr = new int[n];
        System.arraycopy(path, 0, srcArr, 0, n);
        System.arraycopy(path, n, dstArr, 0, n);
        String srcKey = serialize.apply(srcArr);
        String dstKey = serialize.apply(dstArr);
        adj.computeIfAbsent(srcKey, k -> new java.util.ArrayList<>()).add(dstKey);
        adj.computeIfAbsent(dstKey, k -> new java.util.ArrayList<>()).add(srcKey);
    }

    // BFS
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) continue;
        for (String next : neighbors) {
            if (!visited.contains(next)) {
                if (next.equals(endKey)) return "can be travelled";
                visited.add(next);
                queue.offer(next);
            }
        }
    }
    return "cannot be travelled";
}

