public static String convertDatesToWeekdays(String date) {
    String[] parts = date.split(" ");
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
    java.time.DayOfWeek dow = localDate.getDayOfWeek();
    java.time.Month monthEnum = java.time.Month.of(month);

    java.util.Locale locale = java.util.Locale.ENGLISH;
    String monthName = monthEnum.getDisplayName(java.time.format.TextStyle.FULL, locale);
    String weekdayName = dow.getDisplayName(java.time.format.TextStyle.FULL, locale);

    return String.format("%s %d, %d is a %s", monthName, day, year, weekdayName);
}

public static String convertDatesToWeekdays(String date) {
    // Split the input date string by whitespace
    String[] parts = date.split("\\s+");
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    // Keep original month and year for output formatting
    int originalMonth = month;
    int originalYear = year;

    // Zeller's Congruence algorithm for Gregorian calendar
    if (month <= 2) {
        month += 12;
        year -= 1;
    }
    int q = day;
    int m = month;
    int K = year % 100;
    int J = year / 100;
    int h = (q + (13 * (m + 1)) / 5 + K + K / 4 + J / 4 + 5 * J) % 7; // 0=Saturday

    // Day names mapping according to Zeller's output
    String[] dayNames = {"Saturday", "Sunday", "Monday", "Tuesday",
                         "Wednesday", "Thursday", "Friday"};
    String dayName = dayNames[h];

    // Full month names
    String[] monthNames = {"January", "February", "March", "April",
                           "May", "June", "July", "August",
                           "September", "October", "November", "December"};
    String monthName = monthNames[originalMonth - 1];

    return monthName + " " + day + ", " + originalYear + " is a " + dayName;
}

