public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) return false;
    if (k <= 0) return false; // invalid divisor

    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        count[r]++;
    }

    // Check remainder 0
    if (count[0] % 2 != 0) return false;

    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // only when k is even and r == k/2
            if (count[r] % 2 != 0) return false;
        } else {
            if (count[r] != count[complement]) return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (k <= 0) {
        // Problem statement assumes k > 0; otherwise sum divisible by zero is undefined
        return false;
    }
    if (arr == null) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    if (n == 0) {
        return true;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) {
            rem += k;
        }
        freq[rem]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    for (int r = 1; r < k; r++) {
        int complement = k - r;
        if (r == complement) {
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else if (r < complement) {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (k <= 0) {
        return false; // invalid divisor
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false; // Cannot pair all elements
    }
    int[] freq = new int[k];
    for (int val : arr) {
        int r = ((val % k) + k) % k; // ensure non‑negative remainder
        freq[r]++;
    }
    // Count residue 0 elements
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, residue k/2 must also be even
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // For other residues
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // this case handled above when k even
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

