    }
    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // Check pairs of remainders
    for (int r = 1; r < k; r++) {
        if (r == k - r) {
            continue; // already handled for k even
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // ensure non-negative remainder
        freq[r]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    int limit = k / 2;
    for (int r = 1; r <= limit; r++) {
        int complement = k - r;
        if (r == complement) { // k even, r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

