    }
    for (int[] e : edges) {
        int a = e[0], b = e[1];
        adj[a].add(b);
        adj[b].add(a);
    }
    final int[] ans = {0};

    class Solver {
        boolean dfs(int u, int parent) {
            boolean has = hasApple[u];
            for (int v : adj[u]) {
                if (v == parent) continue;
                if (dfs(v, u)) {
                    ans[0] += 2;
                    has = true;
                }
            }
            return has;
        }
    }

    new Solver().dfs(0, -1);
    return ans[0];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build adjacency list
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        int u = e[0], v = e[1];
        adj[u].add(v);
        adj[v].add(u);
    }

    // parent array and order for post-order traversal
    int[] parent = new int[n];
    int[] order = new int[n];
    java.util.Arrays.fill(parent, -2); // -2 means unvisited
    int idx = 0;
    int[] stack = new int[n];
    int top = 0;
    stack[top++] = 0;
    parent[0] = -1; // root's parent

    while (top > 0) {
        int node = stack[--top];
        order[idx++] = node;
        for (int nb : adj[node]) {
            if (parent[nb] == -2) { // not visited
                parent[nb] = node;
                stack[top++] = nb;
            }
        }
    }

    // Boolean array indicating whether a subtree has an apple
    boolean[] subtreeHasApple = new boolean[n];
    System.arraycopy(hasApple, 0, subtreeHasApple, 0, n);
    int totalTime = 0;

    // Process nodes in reverse order (post-order) excluding the root
    for (int i = n - 1; i > 0; i--) {
        int node = order[i];
        int p = parent[node];
        if (subtreeHasApple[node]) {
            totalTime += 2;
            subtreeHasApple[p] = true;
        }
    }

    return totalTime;
}

public String sortString(String s) {
    int[] count = new int[256];
    for (int i = 0; i < s.length(); i++) {
        count[s.charAt(i)]++;
    }
    StringBuilder sb = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass: pick smallest remaining characters in increasing order
        for (int i = 0; i < 256 && remaining > 0; i++) {
            if (count[i] > 0) {
                sb.append((char) i);
                count[i]--;
                remaining--;
            }
        }
        // Descending pass: pick largest remaining characters in decreasing order
        for (int i = 255; i >= 0 && remaining > 0; i--) {
            if (count[i] > 0) {
                sb.append((char) i);
                count[i]--;
                remaining--;
            }
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }
    StringBuilder sb = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        int ascLast = -1;
        // Ascending pass
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0 && i > ascLast) {
                sb.append((char) ('a' + i));
                count[i]--;
                remaining--;
                ascLast = i;
            }
        }
        // Descending pass
        int descLast = ascLast;
        for (int i = 25; i >= 0; i--) {
            if (count[i] > 0 && i < descLast) {
                sb.append((char) ('a' + i));
                count[i]--;
                remaining--;
                descLast = i;
            }
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    int n = s.length();
    int[] freq = new int[65536];
    for (int i = 0; i < n; i++) {
        freq[s.charAt(i)]++;
    }
    StringBuilder sb = new StringBuilder(n);
    int total = n;
    while (total > 0) {
        // Step 1: pick smallest character remaining
        int c = -1;
        for (int i = 0; i < 65536; i++) {
            if (freq[i] > 0) {
                c = i;
                break;
            }
        }
        if (c == -1) break;
        sb.append((char) c);
        freq[c]--;
        total--;
        int prev = c;

        // Step 2: increasing sequence
        while (true) {
            int next = -1;
            for (int i = prev + 1; i < 65536; i++) {
                if (freq[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) break;
            sb.append((char) next);
            freq[next]--;
            total--;
            prev = next;
        }

        if (total == 0) break;

        // Step 4: pick largest character remaining
        int d = -1;
        for (int i = 65535; i >= 0; i--) {
            if (freq[i] > 0) {
                d = i;
                break;
            }
        }
        if (d == -1) break;
        sb.append((char) d);
        freq[d]--;
        total--;
        int prev2 = d;

        // Step 5: decreasing sequence
        while (true) {
            int next2 = -1;
            for (int i = prev2 - 1; i >= 0; i--) {
                if (freq[i] > 0) {
                    next2 = i;
                    break;
                }
            }
            if (next2 == -1) break;
            sb.append((char) next2);
            freq[next2]--;
            total--;
            prev2 = next2;
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int sum = 0;
    for (int num : nums) sum += num;
    int maxK = n / 2;
    for (int k = 1; k <= maxK; k++) {
        if ((long) sum * k % n != 0) continue;
        int target = (int) ((long) sum * k / n);
        @SuppressWarnings("unchecked")
        java.util.HashSet<Integer>[] dp = new java.util.HashSet[k + 1];
        for (int i = 0; i <= k; i++) dp[i] = new java.util.HashSet<>();
        dp[0].add(0);
        for (int num : nums) {
            for (int len = k; len >= 1; len--) {
                if (dp[len - 1].isEmpty()) continue;
                for (int s : dp[len - 1]) {
                    dp[len].add(s + num);
                }
            }
        }
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // Try every possible split size k (1 to n-1)
    for (int k = 1; k <= n / 2; ++k) {
        if ((totalSum * k) % n != 0) continue; // average must be integer
        int targetSum = (totalSum * k) / n;
        // Memoization map: key -> (index,k,targetSum)
        java.util.HashMap<Long, Boolean> memo = new java.util.HashMap<>();
        if (dfs(nums, 0, k, targetSum, memo)) return true;
    }
    return false;
}

private boolean dfs(int[] nums, int index, int k, int target, java.util.HashMap<Long, Boolean> memo) {
    if (k == 0) return target == 0;
    if (index >= nums.length) return false;
    // If there are not enough numbers left to fill k slots
    if (k > nums.length - index) return false;
    // Compute memo key
    long key = (((long)index) << 32) | (((long)k) << 24) | ((long)target & 0xFFFFFFL);
    Boolean cached = memo.get(key);
    if (cached != null) return cached;

    // Prune: if target less than 0 or too large
    if (target < 0) { memo.put(key, false); return false; }

    // Choose current number
    boolean take = dfs(nums, index + 1, k - 1, target - nums[index], memo);
    if (take) { memo.put(key, true); return true; }
    // Skip current number
    boolean skip = dfs(nums, index + 1, k, target, memo);
    memo.put(key, skip);
    return skip;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    int maxK = n / 2;
    // dp[k][s] indicates whether we can pick k numbers summing to s
    boolean[][] dp = new boolean[maxK + 1][totalSum + 1];
    dp[0][0] = true;
    for (int num : nums) {
        // iterate k in reverse to avoid reuse of num in same iteration
        for (int k = Math.min(maxK, n); k >= 1; k--) {
            for (int s = totalSum; s >= num; s--) {
                if (dp[k - 1][s - num]) dp[k][s] = true;
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((totalSum * k) % n != 0) continue; // target sum must be integer
        int target = (totalSum * k) / n;
        if (dp[k][target]) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // dp[k][s] == true if we can pick k elements summing to s
    boolean[][] dp = new boolean[n + 1][totalSum + 1];
    dp[0][0] = true;
    for (int num : nums) {
        // iterate sizes backward to avoid reuse of same element
        for (int k = n - 1; k >= 0; k--) {
            for (int s = 0; s <= totalSum - num; s++) {
                if (dp[k][s]) {
                    dp[k + 1][s + num] = true;
                }
            }
        }
    }
    // check for any split size k (1 <= k <= n/2)
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k][target]) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int total = 0;
    for (int num : nums) total += num;

    @SuppressWarnings("unchecked")
    HashSet<Integer>[] sets = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) sets[i] = new HashSet<>();
    sets[0].add(0);

    for (int num : nums) {
        for (int k = n - 1; k >= 1; k--) {
            if (sets[k - 1].isEmpty()) continue;
            for (int s : sets[k - 1]) {
                sets[k].add(s + num);
            }
        }
    }

    for (int k = 1; k <= n - 1; k++) {
        if ((total * k) % n != 0) continue;
        int target = (total * k) / n;
        if (sets[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int curr = Math.min(prev1, prev2) + cost[i - 1];
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    int a = 0, b = 0;
    for (int c : cost) {
        int newCost = Math.min(a, b) + c;
        a = b;
        b = newCost;
    }
    return Math.min(a, b);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int first = 0;
    int second = 0;
    for (int i = 2; i <= n; i++) {
        int climb = Math.min(first + cost[i - 2], second + cost[i - 1]);
        first = second;
        second = climb;
    }
    return second;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    int prev1 = 0; // cost to reach step 0
    int prev2 = 0; // cost to reach step 1
    for (int i = 2; i <= n; i++) {
        int curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev1 = prev2;
        prev2 = curr;
    }
    return prev2;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

