public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k <= 0) return true;
    int totalCodes = 1 << k;          // number of possible binary strings of length k
    if (n < k || totalCodes > n - k + 1) return false;

    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;        // for keeping only k bits
    int code = 0;
    int count = 0;

    for (int i = 0; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {                 // only start counting after first full window
            if (!seen[code]) {
                seen[code] = true;
                count++;
                if (count == totalCodes) {
                    return true;
                }
            }
        }
    }
    return false;
}

