        } else { // c == ')'
            if (balance == 0) {
                ans++;        // need an opening '(' before this ')'
            } else {
                balance--;    // match this ')' with an existing '('
            }
        }
    }
    ans += balance; // add closing ')' for unmatched '('
    return ans;
}

