public int findMinFibonacciNumbers(int k) {
    int[] fib = new int[50];
    fib[0] = 1;
    fib[1] = 1;
    int size = 2;
    while (fib[size - 1] <= k) {
        fib[size] = fib[size - 1] + fib[size - 2];
        size++;
    }
    int count = 0;
    while (k > 0) {
        for (int i = size - 1; i >= 0; i--) {
            if (fib[i] <= k) {
                k -= fib[i];
                count++;
                break;
            }
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
