    while (fibs.get(fibs.size() - 2) + fibs.get(fibs.size() - 1) <= k) {
        int next = fibs.get(fibs.size() - 2) + fibs.get(fibs.size() - 1);
        fibs.add(next);
    }
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        remaining -= fibs.get(i);
        count++;
    }
    return count;
}

