public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    java.util.ArrayList<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int sz = fib.size();
        long next = (long) fib.get(sz - 1) + (long) fib.get(sz - 2);
        if (next > k) break;
        fib.add((int) next);
    }
    int count = 0;
    int remaining = k;
    for (int i = fib.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fib.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // 50 is sufficient for int range
    int len = 0;
    fib[len++] = 1;
    if (k > 1) {
        fib[len++] = 1;
    }
    while (true) {
        long next = (long) fib[len - 1] + fib[len - 2];
        if (next > k) break;
        fib[len++] = (int) next;
    }

    int count = 0;
    int remaining = k;
    int i = len - 1;
    while (remaining > 0) {
        while (fib[i] > remaining) {
            i--;
        }
        remaining -= fib[i];
        count++;
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    int sqrtN = (int)Math.sqrt(n);
    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k <= 0 || k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public int kthFactor(int n, int k) {
    ArrayList<Integer> small = new ArrayList<>();
    ArrayList<Integer> large = new ArrayList<>();
    for (int i = 1; (long)i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int idxLarge = k - small.size() - 1;
        return large.get(large.size() - 1 - idxLarge);
    }
}

public int kthFactor(int n, int k) {
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();
    int limit = (int)Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small.add(i);
            int counterpart = n / i;
            if (counterpart != i) {
                large.add(counterpart);
            }
        }
    }
    // Combine small factors and reversed large factors to get sorted ascending list
    int totalFactors = small.size() + large.size();
    if (k > totalFactors) return -1;
    // If k <= small.size(), return directly from small
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        // k is in the large part
        int idxInLarge = k - small.size() - 1; // 0-based index in reverse order
        // Since large is in descending order, index from end
        return large.get(large.size() - 1 - idxInLarge);
    }
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }
    java.util.Collections.sort(factors);
    return k <= factors.size() ? factors.get(k - 1) : -1;
}

public int kthFactor(int n, int k) {
