    java.util.List<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int divisor = n / i;
            if (divisor != i) {
                large.add(divisor);
            }
        }
    }
    // large currently in descending order; reverse it for ascending
    java.util.Collections.reverse(large);
    int totalFactors = small.size() + large.size();
    if (k > totalFactors) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    }
    return large.get(k - small.size() - 1);
}

