public String makeGood(String s) {
    // Use a StringBuilder as a stack to store characters.
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            // Check if c and top are the same letter in different cases.
            if (Math.abs(c - top) == 32) {
                // They cancel each other out.
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        // No cancellation, push current character onto stack.
        stack.append(c);
    }
    return stack.toString();
}

