public int maxUniqueSplit(String s) {
    int n = s.length();
    int maxCount = 0;
    int totalMasks = 1 << (n - 1);
    for (int mask = 0; mask < totalMasks; mask++) {
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        int start = 0;
        boolean valid = true;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) {
                String part = s.substring(start, i + 1);
                if (!seen.add(part)) {
                    valid = false;
                    break;
                }
                start = i + 1;
            }
        }
        if (!valid) continue;
        // last part
        String lastPart = s.substring(start);
        if (!seen.add(lastPart)) {
            continue;
        }
        maxCount = Math.max(maxCount, seen.size());
    }
    return maxCount;
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] best = new int[]{0};
    Set<String> used = new HashSet<>();
    dfs(0, 0, used, s, best, n);
    return best[0];
}

private void dfs(int pos, int count, Set<String> used, String s, int[] best, int n) {
    if (pos == n) {
        if (count > best[0]) best[0] = count;
        return;
    }
    // Prune if even taking every remaining character separately can't beat current best
    if (count + (n - pos) <= best[0]) return;

    for (int i = pos + 1; i <= n; i++) {
        String sub = s.substring(pos, i);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(i, count + 1, used, s, best, n);
            used.remove(sub);
        }
    }
}

