private int dfs(String s, int pos, java.util.Set<String> used) {
    int n = s.length();
    if (pos == n) {
        return 0;
    }
    int best = 0;
    for (int i = pos + 1; i <= n; i++) {
        String sub = s.substring(pos, i);
        if (!used.contains(sub)) {
            used.add(sub);
            int res = 1 + dfs(s, i, used);
            if (res > best) {
                best = res;
            }
            used.remove(sub);
        }
    }
    return best;
}

