    int max = 0;
    for (int i = pos + 1; i <= s.length(); i++) {
        String sub = s.substring(pos, i);
        if (!used.contains(sub)) {
            used.add(sub);
            int res = 1 + dfs(s, i, used);
            if (res > max) max = res;
            used.remove(sub);
        }
    }
    return max;
}

