private int dfs(int idx, String s, java.util.Set<String> used) {
    if (idx == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = idx + 1; end <= s.length(); end++) {
        String sub = s.substring(idx, end);
        if (!used.contains(sub)) {
            used.add(sub);
            max = Math.max(max, 1 + dfs(end, s, used));
            used.remove(sub);
        }
    }
    return max;
}

