public static int singleNumber(int[] nums) {
    int ones = 0;
    int twos = 0;
    for (int x : nums) {
        twos |= ones & x;
        ones ^= x;
        int mask = ~(ones & twos);
        ones &= mask;
        twos &= mask;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
