    Set<Integer> resultSet = new TreeSet<>();
    Queue<Long> queue = new LinkedList<>();

    // Add starting digits 1-9 to queue
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }

    // Include 0 if it falls within the range
    if (low == 0) {
        resultSet.add(0);
    }

    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            resultSet.add((int) num);
        }
        int lastDigit = (int) (num % 10);
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    return new ArrayList<>(resultSet);
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    // Single digit stepping numbers
    for (int d = 0; d <= 9; d++) {
        if (d >= low && d <= high) {
            result.add(d);
        }
    }

    Queue<Integer> queue = new LinkedList<>();
    // Start BFS from digits 1 to 9
    for (int d = 1; d <= 9; d++) {
        if (d <= high) {
            queue.offer(d);
        }
    }

    while (!queue.isEmpty()) {
        int current = queue.poll();
        // No need to expand if current is already too large for further digits
        if (current > high / 10) {
            continue;
        }
        int lastDigit = current % 10;
        int[] candidates = {lastDigit - 1, lastDigit + 1};
        for (int nextDigit : candidates) {
            if (nextDigit < 0 || nextDigit > 9) {
                continue;
            }
            long nextLong = (long) current * 10 + nextDigit;
            if (nextLong > high) {
                continue;
            }
            int next = (int) nextLong;
            if (next >= low) {
                result.add(next);
            }
            queue.offer(next);
        }
    }

    Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low < 0) low = 0; // stepping numbers are non-negative
    if (low > high) return result;
    if (low == 0) result.add(0); // 0 is a stepping number
    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        if (i <= high) queue.offer((long)i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num >= low && num <= high) result.add((int)num);
        if (num > high / 10) continue; // no need to extend further
        long lastDigit = num % 10;
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) queue.offer(next);
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) queue.offer(next);
        }
    }
    Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    // Include 0 if it lies in the range
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    // Breadth-first search for stepping numbers
    Deque<Long> queue = new ArrayDeque<>();
    // Start with single digit numbers 1-9
    for (int d = 1; d <= 9; d++) {
        if (d <= high) {
            queue.offer((long) d);
        }
    }
    while (!queue.isEmpty()) {
        long cur = queue.poll();
        if (cur >= low) {
            result.add((int) cur);
        }
        // Generate next stepping numbers by appending last digit +/- 1
        long lastDigit = cur % 10;
        if (lastDigit < 9) {
            long next = cur * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit > 0) {
            long next = cur * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    long num = n;
    while (factor <= num) {
        long lower = num - (num / factor) * factor;
        long cur = (num / factor) % 10;
        long higher = num / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + (lower + 1);
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

