public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    // dp[i][j][dir] where dir: 0=horizontal, 1=vertical, 2=diagonal \, 3=anti-diagonal /
    int[][][] dp = new int[m][n][4];
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // horizontal
                dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1;
                // vertical
                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1;
                // diagonal (\)
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1;
                // anti-diagonal (/)
                dp[i][j][3] = (i > 0 && j + 1 < n ? dp[i - 1][j + 1][3] : 0) + 1;
                // update maximum
                for (int dir = 0; dir < 4; dir++) {
                    if (dp[i][j][dir] > maxLen) {
                        maxLen = dp[i][j][dir];
                    }
                }
            }
        }
    }
    return maxLen;
}

