        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }
    sb.reverse();
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int maxSum = 2 * maxVal;
    // Precompute perfect squares up to maxSum
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int x = 0; x * x <= maxSum; x++) {
        isSquare[x * x] = true;
    }
    // Build adjacency matrix
    boolean[][] adj = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && isSquare[A[i] + A[j]]) {
                adj[i][j] = true;
            }
        }
    }
    int maxMask = 1 << n;
    long[][] dp = new long[maxMask][n];
    // Initialize with single element permutations
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    // DP over subsets
    for (int mask = 1; mask < maxMask; mask++) {
        for (int last = 0; last < n; last++) {
            long cur = dp[mask][last];
            if (cur == 0) continue;
            // try to append next element
            int remaining = (~mask) & (maxMask - 1);
            for (int next = 0; next < n; next++) {
                if ((remaining & (1 << next)) != 0 && adj[last][next]) {
                    dp[mask | (1 << next)][next] += cur;
                }
            }
        }
    }
    long result = 0;
    int fullMask = maxMask - 1;
    for (int last = 0; last < n; last++) {
        result += dp[fullMask][last];
    }
    return (int) result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Sort array to handle duplicates
    java.util.Arrays.sort(A);
    int maxVal = A[n - 1];
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 1; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    // adjacency list
    int[][] adj = new int[n][];
    int[][] temp = new int[n][n];
    int[] count = new int[n];
    for (int i = 0; i < n; i++) {
        int[] arr = new int[n];
        int c = 0;
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            if (isSquare[A[i] + A[j]]) {
                arr[c++] = j;
            }
        }
        temp[i] = arr;
        count[i] = c;
    }
    for (int i = 0; i < n; i++) {
        int[] arr = new int[count[i]];
        System.arraycopy(temp[i], 0, arr, 0, count[i]);
        adj[i] = arr;
    }
    int fullMask = (1 << n) - 1;
    int[][] memo = new int[1 << n][n];
    for (int i = 0; i < memo.length; i++) {
        java.util.Arrays.fill(memo[i], -1);
    }
    java.util.function.BiFunction<Integer,Integer,Integer> dfs = new java.util.function.BiFunction<>() {
        @Override
        public Integer apply(Integer mask, Integer last) {
            if (mask == fullMask) return 1;
            int cached = memo[mask][last];
            if (cached != -1) return cached;
            int res = 0;
            for (int next : adj[last]) {
                if ((mask & (1 << next)) != 0) continue;
                // skip duplicates: if next>0, values equal to previous, and previous not used yet in mask
                if (next > 0 && A[next] == A[next - 1] && (mask & (1 << (next - 1))) == 0) continue;
                res += apply(mask | (1 << next), next);
            }
            memo[mask][last] = res;
            return res;
        }
    };
    int total = 0;
    for (int i = 0; i < n; i++) {
        // skip duplicate starting indices
        if (i > 0 && A[i] == A[i - 1]) continue;
        total += dfs.apply(1 << i, i);
    }
    return total;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    // Precompute perfect squares up to maximum possible sum
    int maxSum = 2 * 1000 + 1; // assuming A[i] <= 1000; adjust if needed
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    // DP[mask][last] = number of ways to arrange indices in mask ending with index last
    int maxMask = 1 << n;
    long[][] dp = new long[maxMask][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    for (int mask = 1; mask < maxMask; mask++) {
        for (int last = 0; last < n; last++) {
            long cur = dp[mask][last];
            if (cur == 0) continue;
            for (int nxt = 0; nxt < n; nxt++) {
                if ((mask & (1 << nxt)) != 0) continue; // already used
                int sum = A[last] + A[nxt];
                if (sum < isSquare.length && isSquare[sum]) {
                    dp[mask | (1 << nxt)][nxt] += cur;
                }
            }
        }
    }
    long total = 0;
    int fullMask = maxMask - 1;
    for (int last = 0; last < n; last++) {
        total += dp[fullMask][last];
    }
    // Divide by factorials of duplicate counts
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int v : A) {
        freq.put(v, freq.getOrDefault(v, 0) + 1);
    }
    long dupFactor = 1;
    for (int count : freq.values()) {
        long fact = 1;
        for (int i = 2; i <= count; i++) fact *= i;
        dupFactor *= fact;
    }
    long answer = total / dupFactor;
    return (int) answer;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    java.util.Arrays.sort(A);
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int limit = maxVal * 2 + 1;
    boolean[] isSq = new boolean[limit];
    for (int i = 0; i * i < limit; i++) {
        isSq[i * i] = true;
    }
    java.util.Map<Long, Long> memo = new java.util.HashMap<>();

    java.util.function.IntUnaryOperator dfs = new java.util.function.IntUnaryOperator() {
        @Override
        public int applyAsInt(int mask) {
            return 0; // placeholder
        }
    };
    java.util.function.Function<long[], Long> backtrack = new java.util.function.Function<long[], Long>() {
        @Override
        public Long apply(long[] state) {
            int mask = (int) state[0];
            int lastIdx = (int) state[1];
            if (mask == (1 << n) - 1) {
                return 1L;
            }
            long key = (((long) mask) << 32) | ((lastIdx == -1) ? n : lastIdx);
            Long cached = memo.get(key);
            if (cached != null) return cached;
            long sum = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
                if (lastIdx == -1 || isSq[A[i] + A[lastIdx]]) {
                    sum += apply(new long[]{mask | (1 << i), i});
                }
            }
            memo.put(key, sum);
            return sum;
        }
    };
    long result = backtrack.apply(new long[]{0, -1});
    return (int) result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    // Build a map of each unique value to its count
    java.util.Map<Integer, Integer> map = new java.util.HashMap<>();
    for (int v : A) {
        map.put(v, map.getOrDefault(v, 0) + 1);
    }
    int m = map.size();
    int[] uniq = new int[m];
    int[] cnt = new int[m];
    int idx = 0;
    for (java.util.Map.Entry<Integer, Integer> e : map.entrySet()) {
        uniq[idx] = e.getKey();
        cnt[idx] = e.getValue();
        idx++;
    }

    // Precompute perfect squares up to the largest possible sum
    int maxSum = 0;
    for (int u : uniq) {
        if (2 * u > maxSum) {
            maxSum = 2 * u;
        }
    }
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int s = 0; s * s <= maxSum; s++) {
        isSquare[s * s] = true;
    }

    // Build adjacency matrix indicating whether two values can be adjacent
    boolean[][] can = new boolean[m][m];
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < m; j++) {
            can[i][j] = isSquare[uniq[i] + uniq[j]];
        }
    }

    long result = rec(uniq, cnt, -1, n, can);
    return (int) result;
}

private static long rec(int[] uniq, int[] cnt, int prev, int remaining, boolean[][] can) {
    if (remaining == 0) {
        return 1;
    }
    long total = 0;
    for (int i = 0; i < uniq.length; i++) {
        if (cnt[i] > 0) {
            if (prev == -1 || can[prev][i]) {
                cnt[i]--;
                total += rec(uniq, cnt, i, remaining - 1, can);
                cnt[i]++;
            }
        }
    }
    return total;
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;
    for (int i = 0; i <= n; i++) {
        int current = (i == n) ? 0 : heights[i];
        while (top != -1 && current < heights[stack[top]]) {
            int h = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = h * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

