public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    if (m == 0) return new int[0];
    int n = mat[0].length;
    if (n == 0) return new int[0];
    int[] res = new int[m * n];
    int idx = 0;
    for (int s = 0; s <= m + n - 2; s++) {
        if ((s & 1) == 0) { // even diagonal: move up-right
            int r = Math.min(s, m - 1);
            int c = s - r;
            while (r >= 0 && c < n) {
                res[idx++] = mat[r][c];
                r--;
                c++;
            }
        } else { // odd diagonal: move down-left
            int c = Math.min(s, n - 1);
            int r = s - c;
            while (c >= 0 && r < m) {
                res[idx++] = mat[r][c];
                r++;
                c--;
            }
        }
    }
    return res;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] res = new int[m * n];
    int idx = 0;
    int totalDiagonals = m + n - 1;
    for (int d = 0; d < totalDiagonals; d++) {
        int startRow = Math.max(0, d - (n - 1));
        int endRow = Math.min(m - 1, d);
        if ((d & 1) == 0) {
            for (int r = endRow; r >= startRow; r--) {
                int c = d - r;
                res[idx++] = mat[r][c];
            }
        } else {
            for (int r = startRow; r <= endRow; r++) {
                int c = d - r;
                res[idx++] = mat[r][c];
            }
        }
    }
    return res;
}

public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    if (m == 0) return new int[0];
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    int i = 0, j = 0;
    boolean up = true;
    while (idx < m * n) {
        result[idx++] = mat[i][j];
        if (up) {
            if (j == n - 1) {
                i++;
                up = false;
            } else if (i == 0) {
                j++;
                up = false;
            } else {
                i--;
                j++;
            }
        } else {
            if (i == m - 1) {
                j++;
                up = true;
            } else if (j == 0) {
                i++;
                up = true;
            } else {
                i++;
                j--;
            }
        }
    }
    return result;
}

