public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no higher permutation
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse suffix
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    int result = 0;
    for (char c : digits) {
        result = result * 10 + (c - '0');
    }
    return result;
}

public static int findSmallestInteger(int n) {
    // Convert number to char array of digits
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    // Step 1: find the first index from the right where digits[i] < digits[i + 1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // digits are in non-increasing order; no larger permutation
        return -1;
    }
    // Step 2: find the smallest digit greater than digits[i] in the suffix
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // Step 3: swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Step 4: reverse the suffix starting at i + 1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    // Convert back to integer
    return Integer.parseInt(new String(digits));
}

