public static java.util.List<String> centerSymmetricNumbers(int n) {
    java.util.List<String> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[][] pairs = { {'0', '0'}, {'1', '1'}, {'6', '9'}, {'9', '6'}, {'8', '8'} };
    char[] temp = new char[n];
    build(0, n - 1, n, temp, result, pairs);
    return result;
}

private static void build(int left, int right, int n, char[] temp, java.util.List<String> result, char[][] pairs) {
    if (left > right) {
        result.add(new String(temp));
        return;
    }
    if (left == right) {
        for (char[] p : pairs) {
            if (p[0] != p[1]) {
                continue;
            }
            if (left == 0 && p[0] == '0' && n > 1) {
                continue; // avoid leading zero for length > 1
            }
            temp[left] = p[0];
            result.add(new String(temp));
        }
        return;
    }
    for (char[] p : pairs) {
        if (left == 0 && p[0] == '0' && n > 1) {
            continue; // avoid leading zero for length > 1
        }
        temp[left] = p[0];
        temp[right] = p[1];
        build(left + 1, right - 1, n, temp, result, pairs);
    }
}

