private static void helper(int left, int right, char[] arr, int n, List<String> res,
                           char[] leftDigits, char[] rightDigits, char[] midDigits) {
    if (left > right) {
        if (n > 1 && arr[0] == '0') return;
        res.add(new String(arr));
        return;
    }
    if (left == right) {
        for (char d : midDigits) {
            arr[left] = d;
            helper(left + 1, right - 1, arr, n, res, leftDigits, rightDigits, midDigits);
        }
    } else {
        for (int i = 0; i < leftDigits.length; i++) {
            arr[left] = leftDigits[i];
            arr[right] = rightDigits[i];
            helper(left + 1, right - 1, arr, n, res, leftDigits, rightDigits, midDigits);
        }
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    final List<String> res = new ArrayList<>();
    if (n <= 0) return res;
    final int len = n;
    class Builder {
        void backtrack(char[] arr, int left, int right) {
            if (left > right) {
                res.add(new String(arr));
                return;
            }
            if (left == right) {
                char[] centers = {'0', '1', '8'};
                for (char c : centers) {
                    arr[left] = c;
                    backtrack(arr, left + 1, right - 1);
                }
            } else {
                char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
                for (char[] p : pairs) {
                    if (left == 0 && p[0] == '0' && len > 1) continue;
                    arr[left] = p[0];
                    arr[right] = p[1];
                    backtrack(arr, left + 1, right - 1);
                }
            }
        }
    }
    new Builder().backtrack(new char[len], 0, len - 1);
    return res;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    String[][] pairs = {{"0", "0"}, {"1", "1"}, {"8", "8"}, {"6", "9"}, {"9", "6"}};
    Map<Integer, List<String>> memo = new HashMap<>();
    memo.put(0, List.of(""));
    if (n == 1) {
        memo.put(1, List.of("0", "1", "8"));
    } else {
        memo.put(1, List.of("0", "1", "8"));
    }

    List<String> get(int len) {
        if (memo.containsKey(len)) {
            return memo.get(len);
        }
        List<String> sub = get(len - 2);
        List<String> cur = new ArrayList<>();
        for (String[] p : pairs) {
            for (String mid : sub) {
                if (p[0].equals("0") && len == n) {
                    continue; // avoid leading zero for outermost layer
                }
                cur.add(p[0] + mid + p[1]);
            }
        }
        memo.put(len, cur);
        return cur;
    }

    result = get(n);
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    result.addAll(build(n, n));
    return result;
}

private static List<String> build(int n, int totalLen) {
    if (n == 0) {
        List<String> list = new ArrayList<>();
        list.add("");
        return list;
    }
    if (n == 1) {
        List<String> list = new ArrayList<>();
        list.add("0");
        list.add("1");
        list.add("8");
        return list;
    }
    List<String> prev = build(n - 2, totalLen);
    List<String> res = new ArrayList<>();
    char[][] pairs = { {'0','0'}, {'1','1'}, {'6','9'}, {'8','8'}, {'9','6'} };
    for (String s : prev) {
        for (char[] p : pairs) {
            if (n == totalLen && p[0] == '0') continue; // skip leading zero
            res.add(p[0] + s + p[1]);
        }
    }
    return res;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    // Compute cross product of (p2 - p1) and (p3 - p1)
    int cross = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);
    return cross != 0;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length < 3) {
        return false;
    }
    // Check for duplicate points
    if (points[0][0] == points[1][0] && points[0][1] == points[1][1]) {
        return false;
    }
    if (points[0][0] == points[2][0] && points[0][1] == points[2][1]) {
        return false;
    }
    if (points[1][0] == points[2][0] && points[1][1] == points[2][1]) {
        return false;
    }
    // Compute cross product to test collinearity
    int cross = (points[1][0] - points[0][0]) * (points[2][1] - points[0][1])
              - (points[2][0] - points[0][0]) * (points[1][1] - points[0][1]);
    return cross != 0;
}

