public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int curr = 1;
    while (result.size() < n) {
        result.add(curr);
        if ((long) curr * 10 <= n) {
            curr *= 10;
        } else {
            while ((curr % 10 == 9) || (curr + 1 > n)) {
                curr /= 10;
            }
            curr++;
        }
    }
    return result;
}

