public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int max = n + 1; // maximum number of squares needed (when all 1's)
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = max;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    int start = 0;
    int n = s.length();
    for (int i = 0; i < n; i++) {
        if (s.charAt(i) == ' ') {
            // reverse the word before the space
            result.append(new StringBuilder(s, start, i - start).reverse());
            result.append(' ');
            start = i + 1;
        }
    }
    // reverse the last word
    result.append(new StringBuilder(s, start, n - start).reverse());
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        result.append(new StringBuilder(word).reverse());
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}

